export function wrapArguments(data: T.Arguments, tree: TreeHandle) {
	const _node = withMethods(
		{
			...data,
			$type: TSKindId.Arguments as const,
			_arguments: splitElidedWrapSlot(
				data._arguments,
				[TSKindId.Comma],
				[
					'expression',
					'as_expression',
					'satisfies_expression',
					'instantiation_expression',
					'internal_module',
					'type_assertion',
					'primary_expression',
					'subscript_expression',
					'member_expression',
					'parenthesized_expression',
					'_identifier',
					'undefined',
					'identifier',
					'_reserved_identifier',
					'this',
					'super',
					'number',
					'string',
					'template_string',
					'regex',
					'true',
					'false',
					'null',
					'object',
					'array',
					'function_expression',
					'arrow_function',
					'generator_function',
					'class',
					'meta_property',
					'call_expression',
					'non_null_expression',
					'assignment_expression',
					'augmented_assignment_expression',
					'await_expression',
					'unary_expression',
					'binary_expression',
					'ternary_expression',
					'update_expression',
					'new_expression',
					'yield_expression',
					'spread_element'
				]
			),

			arguments() {
				return drillInAll<T.Expression | T.SpreadElement | undefined>(
					this._arguments as readonly (T.Expression | T.SpreadElement | undefined)[] | undefined,
					tree
				);
			},
			$with: {
				arguments: (...v: NonNullable<T.Arguments['_arguments']>[number][]) =>
					wrapArguments({ ...$edited(data), _arguments: v }, tree)
			}
		},
		_treeEngine(tree)
	);
	return _node;
}

