export function wrapPattern(
	data: T.Pattern & { readonly $other?: T.Pattern | readonly T.Pattern[] },
	tree: TreeHandle
) {
	const kindKeyed = _firstKindKeyedWrapChild(data, [
		'_lhs_expression',
		'lhs_expression',
		'member_expression',
		'subscript_expression',
		'_identifier',
		'identifier',
		'undefined',
		'_reserved_identifier',
		'reserved_identifier',
		'_destructuring_pattern',
		'destructuring_pattern',
		'object_pattern',
		'array_pattern',
		'non_null_expression',
		'rest_pattern'
	]) as T.Pattern | readonly T.Pattern[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(data.$other, [
			'_lhs_expression',
			'lhs_expression',
			'member_expression',
			'subscript_expression',
			'_identifier',
			'identifier',
			'undefined',
			'_reserved_identifier',
			'reserved_identifier',
			'_destructuring_pattern',
			'destructuring_pattern',
			'object_pattern',
			'array_pattern',
			'non_null_expression',
			'rest_pattern'
		]);
	if (filtered === undefined && typeof (data as _NodeData).$text === 'string') {
		return drillInSelf<T.Pattern>(data as T.Pattern, tree);
	}
	return drillIn<T.Pattern>(
		normalizeSingularWrapSlot(filtered, 'children', true, data.$type, {
			tree,
			nodeType: data.$type,
			slotName: 'children',
			span: (data as _NodeData).$span
		}),
		tree
	);
}

