export function wrapObjectTypeContent(
	data: T.ObjectTypeContent & {
		readonly _export_statement?:
			| T.ExportStatement
			| T.PropertySignature
			| T.CallSignature
			| T.ConstructSignature
			| T.IndexSignature
			| T.MethodSignature;
		readonly _property_signature?:
			| T.ExportStatement
			| T.PropertySignature
			| T.CallSignature
			| T.ConstructSignature
			| T.IndexSignature
			| T.MethodSignature;
		readonly _call_signature?:
			| T.ExportStatement
			| T.PropertySignature
			| T.CallSignature
			| T.ConstructSignature
			| T.IndexSignature
			| T.MethodSignature;
		readonly _construct_signature?:
			| T.ExportStatement
			| T.PropertySignature
			| T.CallSignature
			| T.ConstructSignature
			| T.IndexSignature
			| T.MethodSignature;
		readonly _index_signature?:
			| T.ExportStatement
			| T.PropertySignature
			| T.CallSignature
			| T.ConstructSignature
			| T.IndexSignature
			| T.MethodSignature;
		readonly _method_signature?:
			| T.ExportStatement
			| T.PropertySignature
			| T.CallSignature
			| T.ConstructSignature
			| T.IndexSignature
			| T.MethodSignature;
		readonly $other?: _NodeData['$other'];
		readonly $span?: { start: number; end: number };
	},
	tree: TreeHandle
) {
	const _content = normalizeRepeatedWrapSlot(
		data._content !== undefined
			? _toArr(data._content)
			: _interleaveBySlotOrder(data as _NodeData, [
					['export_statement', data._export_statement],
					['property_signature', data._property_signature],
					['call_signature', data._call_signature],
					['construct_signature', data._construct_signature],
					['index_signature', data._index_signature],
					['method_signature', data._method_signature]
				]),
		true,
		'content',
		{ tree, nodeType: data.$type, slotName: 'content', span: (data as _NodeData).$span }
	);
	return withMethods(
		{
			..._omitWrapKeys(data, [
				'_call_signature',
				'_construct_signature',
				'_export_statement',
				'_index_signature',
				'_method_signature',
				'_property_signature'
			]),
			$type: TSKindId.ObjectTypeContent as const,
			_content: _content,
			_separator: _separatorKindOf(data, [TSKindId.Comma, TSKindId.Semi]),
			_delimiter:
				(_hasSeparatorFlank(data, _content, data.$other, 'leading', true, 0) ? Delimiter.Leading : Delimiter.None) |
				(_hasSeparatorFlank(data, _content, data.$other, 'trailing', true, 0) ? Delimiter.Trailing : Delimiter.None),

			contents() {
				return drillInAll<
					| T.ExportStatement
					| T.PropertySignature
					| T.CallSignature
					| T.ConstructSignature
					| T.IndexSignature
					| T.MethodSignature
				>(
					this._content as
						| readonly (
								| T.ExportStatement
								| T.PropertySignature
								| T.CallSignature
								| T.ConstructSignature
								| T.IndexSignature
								| T.MethodSignature
						  )[]
						| undefined,
					tree
				);
			},
			$with: {}
		},
		_treeEngine(tree)
	);
}

